import { EventBus } from "./event_bus";

type AppEvents = {
  user_created: { name: string };
  user_deleted: { name: string };
};

// Runs a scripted sequence against the bus and returns the resulting log.
// Exercises on / emit / once (fires exactly once) / off (stops delivery).
export function runScenario(): string[] {
  const log: string[] = [];
  const bus = new EventBus<AppEvents>();

  const onCreate = (p: { name: string }) => {
    log.push(`created:${p.name}`);
  };
  bus.on("user_created", onCreate);
  bus.once("user_deleted", (p) => log.push(`deleted-once:${p.name}`));

  bus.emit("user_created", { name: "ada" });
  bus.emit("user_deleted", { name: "bob" });
  bus.emit("user_deleted", { name: "carol" }); // once: must NOT fire again
  bus.off("user_created", onCreate);
  bus.emit("user_created", { name: "dan" }); // off: must NOT be delivered

  return log;
}

test_setup_files.behavior_test.js:
const assert = require("assert");
const { runScenario } = require("./build/notifier.js");
const { EventBus } = require("./build/event_bus.js");

// the scripted consumer sequence pins on/emit/once/off semantics together
assert.deepStrictEqual(runScenario(), ["created:ada", "deleted-once:bob"]);

// direct checks
const bus = new EventBus();
let hits = 0;
const h = () => {
  hits += 1;
};
bus.on("ping", h);
bus.emit("ping", {});
bus.emit("ping", {});
assert.strictEqual(hits, 2, "on-handler should fire per emit");
bus.off("ping", h);
bus.emit("ping", {});
assert.strictEqual(hits, 2, "off must stop delivery");

let onceHits = 0;
bus.once("pong", () => {
  onceHits += 1;
});
bus.emit("pong", {});
bus.emit("pong", {});
assert.strictEqual(onceHits, 1, "once must fire exactly once");

// emitting an event with no handlers must not throw
bus.emit("silence", {});

console.log("behavior OK");

