type Handler<T> = (payload: T) => void;

// Minimal strongly-typed pub/sub bus. The Events map ties each event name to
// its payload type, so on/emit are type-checked per event.
export class EventBus<Events extends Record<string, unknown>> {
  private handlers = new Map<keyof Events, Handler<never>[]>();

  on<K extends keyof Events>(event: K, handler: Handler<Events[K]>): void {
    const list = this.handlers.get(event) ?? [];
    list.push(handler as Handler<never>);
    this.handlers.set(event, list);
  }

  off<K extends keyof Events>(event: K, handler: Handler<Events[K]>): void {
    const list = this.handlers.get(event);
    if (!list) {
      return;
    }
    const idx = list.indexOf(handler as Handler<never>);
    if (idx >= 0) {
      list.splice(idx, 1);
    }
  }

  once<K extends keyof Events>(event: K, handler: Handler<Events[K]>): void {
    const wrapper = (payload: Events[K]): void => {
      this.off(event, wrapper);
      handler(payload);
    };
    this.on(event, wrapper);
  }

  emit<K extends keyof Events>(event: K, payload: Events[K]): void {
    const list = this.handlers.get(event);
    if (!list) {
      return;
    }
    for (const handler of [...list]) {
      (handler as Handler<Events[K]>)(payload);
    }
  }
}

